package handler;
import com.google.gson.Gson; import entity.*; import protocol.*; import service.StudentService; import session.*; import vo.StudentReviewVO;
public class StudentHandler {
 private final StudentService service=new StudentService();private final Gson gson=new Gson();
 public Message handle(Message q){Message r=new Message(MessageType.RESPONSE,"student",q.getAction());r.setUID(q.getUID());try{UserSession s=SessionManager.getInstance().getSession(q.getToken());if(s==null)return fail(r,MessageCode.UNAUTHORIZED,"请先登录");boolean admin="管理员".equals(s.getRole())||"ADMIN".equalsIgnoreCase(s.getRole());String a=q.getAction()==null?"":q.getAction();switch(a){case"queryOverview"->r.putData("overview",service.queryByUserId(s.getUsername()));case"submitChangeRequest"->r.putData("requestId",service.submit(s.getUsername(),value(q,"request",StudentChangeRequest.class)));case"queryMyRequests"->r.putData("requests",service.listMyRequests(s.getUsername()));case"cancelChangeRequest"->service.cancel(s.getUsername(),number(q,"requestId"));case"listStudents"->{needAdmin(admin);r.putData("students",service.listStudents());}case"queryStudentOverview"->{needAdmin(admin);r.putData("overview",service.queryByStudentId(string(q,"studentId")));}case"listPendingRequests"->{needAdmin(admin);r.putData("requests",service.listPending());}case"queryChangeRequest"->{needAdmin(admin);r.putData("request",service.queryRequest(number(q,"requestId")));}case"reviewChangeRequest"->{needAdmin(admin);StudentReviewVO v=value(q,"review",StudentReviewVO.class);service.review(v.getRequestId(),v.getReviewResult(),s.getUsername(),v.getReviewRemark());}case"updateStudentByAdmin"->{needAdmin(admin);r.putData("updated",service.updateByAdmin(value(q,"student",Student.class)));}case"addAward"->{needAdmin(admin);r.putData("updated",service.addAward(value(q,"award",StudentAward.class)));}case"updateAward"->{needAdmin(admin);r.putData("updated",service.updateAward(value(q,"award",StudentAward.class)));}case"deleteAward"->{needAdmin(admin);r.putData("updated",service.deleteAward(number(q,"awardId")));}case"addAid"->{needAdmin(admin);r.putData("updated",service.addAid(value(q,"aid",StudentAid.class)));}case"updateAid"->{needAdmin(admin);r.putData("updated",service.updateAid(value(q,"aid",StudentAid.class)));}case"deleteAid"->{needAdmin(admin);r.putData("updated",service.deleteAid(number(q,"aidId")));}default->{return fail(r,MessageCode.BAD_REQUEST,"不支持的学籍操作");}}r.setCode(MessageCode.SUCCESS);r.setMessage("操作成功");return r;}catch(SecurityException e){return fail(r,MessageCode.FORBIDDEN,e.getMessage());}catch(IllegalStateException e){return fail(r,MessageCode.CONFLICT,e.getMessage());}catch(IllegalArgumentException e){return fail(r,MessageCode.BAD_REQUEST,e.getMessage());}catch(Exception e){return fail(r,MessageCode.ERROR,"学籍服务异常");}}
 private void needAdmin(boolean b){if(!b)throw new SecurityException("仅管理员可操作");}private String string(Message m,String k){Object v=m.getData().get(k);if(v==null)throw new IllegalArgumentException("缺少参数: "+k);return String.valueOf(v);}private long number(Message m,String k){Object v=m.getData().get(k);return v instanceof Number?((Number)v).longValue():Long.parseLong(string(m,k));}private<T>T value(Message m,String k,Class<T>c){Object v=m.getData().get(k);if(v==null)throw new IllegalArgumentException("缺少参数: "+k);return gson.fromJson(gson.toJson(v),c);}private Message fail(Message m,MessageCode c,String x){m.setCode(c);m.setMessage(x);return m;}
}
